// ============================================
// Circle Distribution - GLSL POP para TouchDesigner
// Fuente: fullscreencode.com/ejemplosshaders/ Cap 4
// Descripción: Puntos distribuidos en círculo con variación
// ============================================

#version 430
layout(local_size_x = 64, local_size_y = 1, local_size_z = 1) in;

#define PI 3.14159265359

uniform float u_time;
uniform int uNumPoints;
uniform float u_radius;      // Radio base (default: 1.0)
uniform float u_waves;       // Number de ondas (default: 20.0)

vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
    uint id = TDIndex();
    if (id >= uNumPoints) return;

    float t = float(id) / float(uNumPoints - 1);

    // Ángulo base + rotación temporal
    float angle = t * 2.0 * PI + u_time * 0.5;

    // Radio con variación ondulada
    float radius = u_radius + sin(t * u_waves + u_time * 2.0) * 0.2;

    // Posición en círculo
    vec3 pos;
    pos.x = cos(angle) * radius;
    pos.y = sin(angle) * radius;
    pos.z = 0.0;

    P[id] = pos;

    // Color basado en posición angular
    vec3 color = hsb2rgb(vec3(t, 0.8, 0.9));
    Cd[id] = vec4(color, 1.0);
}

void main(){
  const uint id = TDIndex();
  if(id >= TDNumElements()) return;
  Cd[id] = vec4(TDIn_P(0,id)*0.5+0.5, 1.0);
}

uniform float u_time;
void main(){
    const uint id = TDIndex();
    if(id >= TDNumElements()) return;
    vec3 p = TDIn_P(0, id);
    // Explosion: push points outward from center over time
    float dist = length(p);
    float force = sin(u_time * 1.5) * 0.5 + 0.5;
    vec3 dir = normalize(p + 0.001);
    float push = force * 2.0 + sin(dist * 2.0 - u_time * 3.0) * 0.3;
    p += dir * push;
    // Spiral rotation
    float a = u_time * 0.5 + dist * 0.3;
    float ct = cos(a), st = sin(a);
    p.xz = mat2(ct, -st, st, ct) * p.xz;
    P[id] = p;
}

// Extreme: glsladvancedPOP extra output (extraout + extraout0name)
// Variable: GLSL_EXTRAOUT_SHADER
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// glsladvancedPOP with extra output - custom velocity attribute
uniform float u_time;
void main() {
    uint id = TDIndex();
    if (id >= TDNumElements()) return;
    vec3 pos = TDIn_P(0, id);
    float angle = atan(pos.z, pos.x) + u_time * 0.3;
    float rad = length(pos.xz);
    pos.x = cos(angle) * rad;
    pos.z = sin(angle) * rad;
    pos.y += sin(u_time + id * 0.01) * 0.1;
    P[id] = pos;
    Cd[id] = vec4(pos.y * 0.3 + 0.5, 0.6, 1.0 - pos.y * 0.3, 1.0);
}

// Extreme: Multi-pass progressive blur (glslTOP, npasses=4)
// Variable: GLSL_MULTIPASS_SHADER
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Multi-pass GLSL TOP - progressive blur using npasses
out vec4 fragColor;
void main() {
    vec2 res = uTD2DInfos[0].res.zw;
    vec4 sum = vec4(0.0);
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            vec2 offset = vec2(float(x), float(y)) * res;
            sum += texture(sTD2DInputs[0], vUV.st + offset);
        }
    }
    vec4 color = sum / 9.0;
    color.g += 0.02;
    fragColor = TDOutputSwizzle(color);
}

// Extreme: glsladvancedPOP primitive compute (glsladvancedPOP)
// Variable: GLSL_PRIM_SHADER
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// glsladvancedPOP primitive compute - color by normal direction
uniform float u_time;
void main() {
    uint id = TDIndex();
    if (id >= TDNumElements()) return;
    vec3 pos = TDIn_P(0, id);
    float wave = sin(u_time + pos.x * 3.0 + pos.y * 2.0) * 0.1;
    P[id] = pos + vec3(0.0, wave, 0.0);
    vec3 n = normalize(pos + vec3(0.001));
    Cd[id] = vec4(n * 0.5 + 0.5, 1.0);
}

// Extreme: GLSL TOP vertex shader - wave deformation (glslTOP vertexdat)
// Variable: GLSL_VERTEX_SHADER
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// GLSL TOP vertex shader - wave deformation of geometry
uniform float u_time;
void main() {
    vec4 pos = P;
    pos.y += sin(u_time * 2.0 + pos.x * 5.0 + pos.z * 3.0) * 0.15;
    pos.x += cos(u_time * 1.5 + pos.z * 4.0) * 0.08;
    gl_Position = TDWorldToProj(TDModelToWorld(pos));
    uv = uvable;
    color = CD;
}

void main(){
  const uint id = TDIndex();
  if(id >= TDNumElements()) return;
  float a = float(id)*0.1 + u_time*2.0;
  P[id] = vec3(sin(a)*2.0, cos(a*0.5)*2.0+2.0, 0.0);
}

uniform float u_time;
void main(){
    const uint id = TDIndex();
    if(id >= TDNumElements()) return;
    float a = float(id) * 0.05 + u_time * 2.0;
    float r = 0.5 + sin(float(id) * 0.3 + u_time) * 0.3;
    float x = cos(a) * r * (1.0 + sin(u_time * 0.7) * 0.3);
    float z = sin(a) * r * (1.0 + cos(u_time * 0.5) * 0.3);
    float y = 2.0 + sin(float(id) * 0.1 + u_time * 1.5) * 1.5 - abs(sin(u_time * 0.3)) * 3.0;
    P[id] = vec3(x, y + 2.0, z);
}

// ============================================
// Fractal Displacement - GLSL POP para TouchDesigner
// Fuente: fullscreencode.com/ejemplosshaders/ Cap 11
// Descripción: Desplazamiento con fractal Julia
// ============================================

#version 430
layout(local_size_x = 64, local_size_y = 1, local_size_z = 1) in;

uniform float u_time;
uniform int uNumPoints;
uniform float u_fractal_scale;  // Escala del fractal (default: 1.5)
uniform vec2 u_julia_c;         // Parámetro Julia (default: vec2(-0.7, 0.27015))

vec2 cmul(vec2 a, vec2 b) {
    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
    uint id = TDIndex();
    if (id >= uNumPoints) return;

    vec3 pos = TDIn_P(0, id);

    // Mapear posición a plano complejo
    vec2 c = pos.xy * u_fractal_scale;
    vec2 z = vec2(0.0);

    // Parámetro Julia animado
    vec2 juliaC = vec2(
        u_julia_c.x + sin(u_time * 0.2) * 0.1,
        u_julia_c.y + cos(u_time * 0.3) * 0.1
    );

    // Iteraciones del fractal
    float iter = 0.0;
    const int MAX_ITER = 20;
    for (int i = 0; i < MAX_ITER; i++) {
        z = cmul(z, z) + juliaC;
        if (dot(z, z) > 4.0) break;
        iter += 1.0;
    }

    // Normalizar iteraciones
    float t = iter / float(MAX_ITER);

    // Color basado en fractal
    vec3 color = hsb2rgb(vec3(t + u_time * 0.1, 0.8, 0.9));

    // Desplazar puntos según fractal
    pos.z += t * 2.0 - 1.0;
    pos.xy += z * 0.1;

    P[id] = pos;
    Cd[id] = vec4(color, 1.0);
}

// ============================================
// Generative Pattern - GLSL POP para TouchDesigner
// Fuente: fullscreencode.com/ejemplosshaders/ Cap 10
// Descripción: Patrón generativo con ruido simplex
// ============================================

#version 430
layout(local_size_x = 64, local_size_y = 1, local_size_z = 1) in;

// #include "util_noise.glsl" // Descomentar si TD encuentra el include

uniform float u_time;
uniform int uNumPoints;

// Simplex noise fallback (si include no está disponible)
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

float snoise(vec3 v) {
    const vec2 C = vec2(1.0/6.0, 1.0/3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);
    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;
    i = mod289(i);
    vec4 p = permute(permute(permute(
        i.z + vec4(0.0, i1.z, i2.z, 1.0))
        + i.y + vec4(0.0, i1.y, i2.y, 1.0))
        + i.x + vec4(0.0, i1.x, i2.x, 1.0));
    float n_ = 0.142857142857;
    vec3 ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);
    vec4 x = x_ *ns.x + ns.yyyy;
    vec4 y = y_ *ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
    vec3 p0 = vec3(a0.xy,h.x);
    vec3 p1 = vec3(a0.zw,h.y);
    vec3 p2 = vec3(a1.xy,h.z);
    vec3 p3 = vec3(a1.zw,h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m*m, vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
}
uniform float u_noise_scale;   // Escala del ruido (default: 2.0)
uniform float u_displacement;  // Fuerza de desplazamiento (default: 0.3)

void main() {
    uint id = TDIndex();
    if (id >= uNumPoints) return;

    vec3 pos = TDIn_P(0, id);

    // Coordenadas para ruido
    vec3 noisePos = pos * u_noise_scale + u_time * 0.3;

    // Múltiples capas de ruido (fractal noise / FBM)
    float n = 0.0;
    n += snoise(noisePos * 1.0) * 0.5;
    n += snoise(noisePos * 2.0) * 0.25;
    n += snoise(noisePos * 4.0) * 0.125;

    // Aplicar desplazamiento orgánico
    pos += vec3(
        n * u_displacement,
        snoise(noisePos + 100.0) * u_displacement,
        snoise(noisePos + 200.0) * u_displacement * 0.5
    );

    P[id] = pos;

    // Color basado en ruido
    vec3 color = vec3(
        n * 0.5 + 0.5,
        snoise(noisePos + 50.0) * 0.5 + 0.5,
        snoise(noisePos + 150.0) * 0.5 + 0.5
    );
    Cd[id] = vec4(color, 1.0);
}

// ============================================
// Grid Pattern - GLSL POP para TouchDesigner
// Fuente: fullscreencode.com/ejemplosshaders/ Cap 6
// Descripción: Puntos distribuidos en grilla con patrón
// ============================================

#version 430
layout(local_size_x = 64, local_size_y = 1, local_size_z = 1) in;

uniform float u_time;
uniform int uNumPoints;
uniform float u_grid_size;   // Tamaño de la grilla (default: 10.0)
uniform float u_wave_amp;    // Amplitud de onda (default: 0.1)

void main() {
    uint id = TDIndex();
    if (id >= uNumPoints) return;

    // Convertir índice a posición 2D en grilla
    float gridSize = ceil(sqrt(float(uNumPoints)));
    float x = mod(float(id), gridSize);
    float y = floor(float(id) / gridSize);

    // Normalizar a [-1, 1]
    vec2 uv = vec2(x, y) / (gridSize - 1.0) * 2.0 - 1.0;

    // Patrón basado en distancia al centro
    float d = length(uv);
    float pattern = smoothstep(0.8, 0.2, d);

    // Animación
    uv += sin(u_time + d * 3.0) * u_wave_amp;

    vec3 pos = vec3(uv, 0.0);
    P[id] = pos;

    // Color por patrón
    vec3 color = vec3(
        pattern,
        uv.x * 0.5 + 0.5,
        uv.y * 0.5 + 0.5
    );
    Cd[id] = vec4(color, 1.0);
}

uniform float u_time;
void main(){
    const uint id = TDIndex();
    if(id >= TDNumElements()) return;
    vec3 p = TDIn_P(0, id);
    float speed = u_time * 0.5;
    // Orbital movement around Y axis
    float angle = atan(p.z, p.x) + speed;
    float rad = length(p.xz);
    p.x = cos(angle) * rad;
    p.z = sin(angle) * rad;
    // Breathing scale
    float breathe = 1.0 + sin(u_time * 1.5 + p.y * 0.5) * 0.15;
    p *= breathe;
    // Wave displacement on Y
    p.y += sin(p.x * 3.0 + u_time * 2.0) * 0.2;
    P[id] = p;
}

void main(){
  const uint id = TDIndex();
  if(id >= TDNumElements()) return;
  float n = TDSimplexNoise(vec4(TDIn_P(0,id)*0.5, u_time*0.3));
  P[id] = TDIn_P(0,id) + TDIn_N(0,id) * n * 0.4;
}

// 10 Bases: Sinusoidal wave displacement (glslPOP)
// Variable: GLSL_WAVE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 01: Sinusoidal wave displacement
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float wave = sin(pos.x * 3.0 + pos.z * 2.0 + u_time * 1.5) * 0.15;
    float wave2 = cos(pos.z * 2.5 + pos.x * 1.8 + u_time * 1.2) * 0.1;
    P[id] = pos + vec3(wave2, wave, wave * 0.5);
}

// 10 Bases: Color by distance (glsladvancedPOP)
// Variable: GLSL_COLOR_DISTANCE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 02: Color by distance from origin
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float d = length(pos);
    P[id] = pos;
    Cd[id] = vec4(
        sin(d * 2.0 + u_time) * 0.5 + 0.5,
        cos(d * 1.5 + u_time * 0.7) * 0.5 + 0.5,
        1.0 - d * 0.3, 1.0);
}

// 10 Bases: Spiral vortex displacement (glsladvancedPOP)
// Variable: GLSL_SPIRAL
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 03: Spiral vortex displacement
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float angle = atan(pos.z, pos.x) + u_time * 0.8;
    float rad = length(pos.xz);
    float spiral = sin(rad * 4.0 - u_time * 3.0) * 0.15;
    pos.x = cos(angle) * rad;
    pos.z = sin(angle) * rad;
    pos.y += spiral;
    P[id] = pos;
    Cd[id] = vec4(sin(angle + u_time) * 0.5 + 0.5, rad * 0.3,
        cos(angle - u_time) * 0.5 + 0.5, 1.0);
}

// 10 Bases: Noise turbulence displacement (glslPOP)
// Variable: GLSL_NOISE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 04: Noise turbulence displacement
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float n1 = TDSimplexNoise(vec4(pos * 2.0, u_time * 0.5));
    float n2 = TDSimplexNoise(vec4(pos * 4.0 + 100.0, u_time * 0.3));
    float n3 = TDSimplexNoise(vec4(pos * 8.0 + 200.0, u_time * 0.2));
    float turbulence = n1 * 0.5 + n2 * 0.3 + n3 * 0.2;
    P[id] = pos + vec3(n1, n2, n3) * 0.2 * turbulence;
}

// 10 Bases: Feedback-aware displacement (glslPOP + feedbackPOP)
// Variable: GLSL_FEEDBACK
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 05: Feedback-aware displacement
// feedbackPOP.inputmul controls temporal blending
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float drift = sin(u_time * 0.4 + pos.x * 2.0 + pos.z * 1.5) * 0.06;
    float drift2 = cos(u_time * 0.3 + pos.y * 1.8 + pos.x * 2.2) * 0.05;
    pos.x += drift; pos.z += drift2;
    pos.y += sin(u_time * 0.2 + id * 0.003) * 0.03;
    P[id] = pos;
}

// 10 Bases: Multi-pass iterative displacement (glslPOP, npasses=4)
// Variable: GLSL_MULTIPASS
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 06: Multi-pass iterative displacement
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float amp = 0.12 / float(uTDPass + 1);
    float wave = sin(pos.x * 5.0 + pos.z * 3.0 + u_time + float(uTDPass) * 1.5) * amp;
    pos.y += wave;
    pos.x += cos(pos.z * 4.0 + u_time * 0.8 + float(uTDPass) * 1.2) * amp * 0.5;
    P[id] = pos;
}

// 10 Bases: Fractal displacement with iterative noise (glslPOP)
// Variable: GLSL_FRACTAL
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 07: Fractal displacement (iterative noise)
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float amp = 0.2; float freq = 1.0;
    vec3 offset = vec3(0.0);
    for (int i = 0; i < 5; i++) {
        float n = TDSimplexNoise(vec4(pos * freq + offset, u_time * 0.3));
        offset += vec3(n * amp, n * amp * 0.5, n * amp * 0.7);
        amp *= 0.5; freq *= 2.0;
    }
    P[id] = pos + offset;
}

// 10 Bases: Attraction field with const params (glsladvancedPOP)
// Variable: GLSL_ATTRACTOR
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 08: Attraction field toward center
// u_strength is set via TD const params (const0name/const0value)
uniform float u_time;
uniform float u_strength;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    vec3 center = vec3(0.0, sin(u_time * 0.5) * 0.3, 0.0);
    vec3 dir = center - pos;
    float dist = length(dir);
    vec3 norm_dir = dist > 0.001 ? dir / dist : vec3(0.0);
    float force = u_strength / (dist * dist + 0.5);
    vec3 orbital = vec3(-pos.z, 0.0, pos.x) * 0.3;
    P[id] = pos + norm_dir * force * 0.05 + orbital * 0.02;
    Cd[id] = vec4(force * 0.5, 1.0 - force * 0.3, 0.8, 1.0);
}

// 10 Bases: Radial ripple wave from center (glslPOP)
// Variable: GLSL_RIPPLE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 09: Radial ripple wave from center
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float dist = length(pos.xz);
    float ripple1 = sin(dist * 8.0 - u_time * 4.0) * 0.08;
    float ripple2 = cos(dist * 5.0 + u_time * 2.5) * 0.05;
    float falloff = exp(-dist * 0.5);
    pos.y += (ripple1 + ripple2) * falloff;
    float pulse = sin(u_time * 1.5) * 0.1 * falloff;
    pos.xz *= 1.0 + pulse;
    P[id] = pos;
}

// 10 Bases: Color cycling animation (glsladvancedPOP)
// Variable: GLSL_COLOR_CYCLE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Base 10: Color cycling animation
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float wave = sin(pos.x * 2.0 + u_time) * 0.08;
    P[id] = pos + vec3(0.0, wave, 0.0);
    float hue = fract(atan(pos.z, pos.x) / 6.283 + u_time * 0.1 + pos.y * 0.3);
    float sat = 0.8 + 0.2 * sin(pos.y * 3.0);
    float val = 0.7 + 0.3 * cos(pos.x * 2.0 + u_time * 0.5);
    vec3 rgb = clamp(abs(mod(hue * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    Cd[id] = vec4(rgb * val * sat, 1.0);
}

// GlslcopyPOP: Hash-based pseudo-noise displacement
