// Tutorials: Particle lifecycle - birth to decay (glsladvancedPOP)
// Variable: GLSL_LIFECYCLE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Tut 07: Particle Age/Lifecycle
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float phase = float(id) * 0.13;
    float age = fract(u_time * 0.15 + phase);
    float scale;
    if (age < 0.2) scale = age / 0.2;
    else if (age < 0.5) scale = 1.0;
    else if (age < 0.8) scale = 1.0;
    else scale = (1.0 - age) / 0.2;
    float angle = age * 6.283 + phase;
    float radius = scale * 1.5;
    P[id] = vec3(cos(angle) * radius, age * 2.0 - 1.0, sin(angle) * radius);
    Cd[id] = vec4(scale, 1.0 - age, age * 0.5, 1.0);
}

// Tutorials: Quaternion rotation - axis-angle rotation (glsladvancedPOP)
// Variable: GLSL_QUATERNION
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Tut 08: Quaternion Rotation (axis-angle)
uniform float u_time;
vec3 rotateAxis(vec3 p, vec3 axis, float angle) {
    float c = cos(angle); float s = sin(angle);
    return p * c + cross(axis, p) * s + axis * dot(axis, p) * (1.0 - c);
}
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    vec3 axis = normalize(vec3(sin(u_time * 0.3), cos(u_time * 0.5), sin(u_time * 0.7)));
    float angle = u_time * 0.8;
    P[id] = rotateAxis(pos, axis, angle);
    Cd[id] = vec4(sin(angle + pos.x) * 0.5 + 0.5, cos(angle + pos.y) * 0.5 + 0.5,
        sin(angle * 0.5 + pos.z) * 0.5 + 0.5, 1.0);
}

// Tutorials: Emergent growth - noise-driven organic (glsladvancedPOP)
// Variable: GLSL_GROWTH
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Tut 09: Emergent Growth Pattern
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float seed = TDSimplexNoise(vec4(pos * 0.5, 0.0, 0.0));
    float growth = smoothstep(-0.3, 0.3, sin(seed * 6.0 + u_time * 0.5));
    float branch = TDSimplexNoise(vec4(pos * 2.0 + seed, u_time * 0.3, 0.0));
    float height = growth * 0.4 + branch * 0.2;
    P[id] = pos + vec3(0.0, height, 0.0);
    Cd[id] = vec4(growth * 0.5, 0.8 - growth * 0.3, branch * 0.5 + 0.3, 1.0);
}

// Tutorials: Audio-reactive heightfield - multi-band simulation (glsladvancedPOP)
// Variable: GLSL_AUDIO_REACTIVE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Tut 10: Audio-Reactive Heightfield (simulated)
uniform float u_time;
void main() {
    uint id = TDIndex();
    vec3 pos = TDIn_P(0, id);
    float x = (pos.x + 2.0) / 4.0;
    float bass = sin(x * 3.0 + u_time * 4.0) * 0.4;
    float mid = sin(x * 15.0 + u_time * 6.0) * 0.2;
    float high = sin(x * 30.0 + u_time * 8.0) * 0.1;
    P[id] = pos + vec3(0.0, (bass + mid + high) * 0.5, 0.0);
    Cd[id] = vec4(abs(bass) * 2.0, abs(mid) * 2.0, abs(high) * 2.0, 1.0);
}

// Vertex: Simplex noise displacement (glslTOP vertexdat)
// Variable: VS_NOISE
//
// TouchDesigner GLSL shader
