//

// Vertex shader: time-based pulse scaling
uniform float u_time;
void main() {
    vec4 pos = P;
    float pulse = 1.0 + sin(u_time * 3.0) * 0.3;
    pos.xyz *= pulse;
    gl_Position = TDWorldToProj(TDModelToWorld(pos));
    uv = uvable;
    color = CD;
}

// Vertex: Twist rotation by Y axis (glslTOP vertexdat)
// Variable: VS_TWIST
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Vertex shader: twist rotation based on Y
uniform float u_time;
void main() {
    vec4 pos = P;
    float twist = pos.y * 2.0 + u_time;
    float c = cos(twist); float s = sin(twist);
    vec3 twisted = vec3(pos.x * c - pos.z * s, pos.y, pos.x * s + pos.z * c);
    gl_Position = TDWorldToProj(TDModelToWorld(vec4(twisted, 1.0)));
    uv = uvable;
    color = CD;
}

// Vertex: Sinusoidal wave deformation (glslTOP vertexdat)
// Variable: VS_WAVE
//
// TouchDesigner GLSL shader
// Use with: glslPOP, glsladvancedPOP, glslTOP, or glslcopyPOP
//

// Vertex shader: sinusoidal wave deformation
uniform float u_time;
void main() {
    vec4 pos = P;
    pos.y += sin(u_time * 2.0 + pos.x * 5.0 + pos.z * 3.0) * 0.15;
    pos.x += cos(u_time * 1.5 + pos.z * 4.0) * 0.08;
    gl_Position = TDWorldToProj(TDModelToWorld(pos));
    uv = uvable;
    color = CD;
}

void main(){
  const uint id = TDIndex();
  if(id >= TDNumElements()) return;
  vec3 p = TDIn_P(0,id);
  p.y += sin(p.x*2.0+u_time*3.0)*0.3;
  P[id] = p;
}

uniform float u_time;
void main(){
    const uint id = TDIndex();
    if(id >= TDNumElements()) return;
    vec3 p = TDIn_P(0, id);
    // Multi-frequency wave deformation
    float w1 = sin(p.x * 1.5 + u_time * 1.2) * 0.4;
    float w2 = cos(p.z * 2.0 + u_time * 0.8) * 0.3;
    float w3 = sin((p.x + p.z) * 1.0 + u_time * 2.5) * 0.2;
    p.y += w1 + w2 + w3;
    // Twist
    float twist = sin(p.y * 0.5 + u_time) * 0.3;
    float ct = cos(twist), st = sin(twist);
    p.xz = mat2(ct, -st, st, ct) * p.xz;
    P[id] = p;
}
